package ca.humber.stockbridge.web;
import ca.humber.stockbridge.model.*;import ca.humber.stockbridge.repo.*;import ca.humber.stockbridge.service.*;import org.springframework.data.domain.*;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.*;import java.math.BigDecimal;import java.security.Principal;
@Controller public class PagesController {private final MaterialRepository materials;private final WarehouseRepository warehouses;private final SupplierRepository suppliers;private final StockLotRepository lots;private final PurchaseRepository purchases;private final SaleRepository sales;private final AppUserRepository users;private final InventoryService inventory;private final AlertClient alerts;public PagesController(MaterialRepository m,WarehouseRepository w,SupplierRepository s,StockLotRepository l,PurchaseRepository p,SaleRepository sa,AppUserRepository u,InventoryService i,AlertClient a){materials=m;warehouses=w;suppliers=s;lots=l;purchases=p;sales=sa;users=u;inventory=i;alerts=a;}@GetMapping("/")String home(){return "home";}@GetMapping("/about")String about(){return "about";}@GetMapping("/how-it-works")String how(){return "how";}@GetMapping("/dashboard")String dashboard(Model model){model.addAttribute("materialCount",materials.count());model.addAttribute("warehouseCount",warehouses.count());model.addAttribute("purchaseCount",purchases.count());model.addAttribute("saleCount",sales.count());model.addAttribute("totalWeight",lots.findAll().stream().map(x->x.weightKg).reduce(BigDecimal.ZERO,BigDecimal::add));model.addAttribute("totalValue",lots.findAll().stream().map(x->x.weightKg.multiply(x.material.basePricePerKg)).reduce(BigDecimal.ZERO,BigDecimal::add));model.addAttribute("recentPurchases",purchases.findAll().stream().sorted((a,b)->b.createdAt.compareTo(a.createdAt)).limit(5).toList());model.addAttribute("remote",alerts.fetch());return "dashboard";}@GetMapping("/materials")String materials(@RequestParam(defaultValue="")String q,@RequestParam(required=false)Material.Category category,@RequestParam(defaultValue="name")String sort,@RequestParam(defaultValue="0")int page,Model model){if(!java.util.Set.of("name","basePricePerKg","createdAt").contains(sort))sort="name";Pageable pageable=PageRequest.of(Math.max(0,page),8,Sort.by(sort));Page<Material> results=category==null?materials.findByNameContainingIgnoreCase(q,pageable):materials.findByNameContainingIgnoreCaseAndCategory(q,category,pageable);model.addAttribute("results",results);model.addAttribute("q",q);model.addAttribute("category",category);model.addAttribute("sort",sort);return "materials";}@GetMapping("/materials/new")String newMaterial(Model model){model.addAttribute("material",new Material());return "material-form";}@PostMapping("/materials/new")String saveMaterial(@jakarta.validation.Valid @ModelAttribute Material material,org.springframework.validation.BindingResult result,Model model){if(result.hasErrors())return "material-form";try{materials.save(material);}catch(Exception ex){model.addAttribute("error","Material name must be unique.");return "material-form";}return "redirect:/materials?created";}@GetMapping("/inventory")String inventory(Model model){model.addAttribute("lots",lots.findAll());return "inventory";}private void selections(Model m){m.addAttribute("materials",materials.findAll());m.addAttribute("warehouses",warehouses.findAll());m.addAttribute("suppliers",suppliers.findAll());}@GetMapping("/purchases/new")String purchase(Model model){selections(model);return "purchase-form";}@PostMapping("/purchases/new")String purchaseSave(@RequestParam Long supplierId,@RequestParam Long materialId,@RequestParam Long warehouseId,@RequestParam BigDecimal weightKg,@RequestParam BigDecimal pricePerKg,Principal principal,Model model){try{inventory.purchase(supplierId,materialId,warehouseId,weightKg,pricePerKg,principal.getName());return "redirect:/dashboard?purchased";}catch(IllegalArgumentException ex){model.addAttribute("error",ex.getMessage());selections(model);return "purchase-form";}}@GetMapping("/sales/new")String sale(Model model){selections(model);return "sale-form";}@PostMapping("/sales/new")String saleSave(@RequestParam String customerName,@RequestParam Long materialId,@RequestParam Long warehouseId,@RequestParam BigDecimal weightKg,@RequestParam BigDecimal pricePerKg,Principal principal,Model model){try{inventory.sell(customerName,materialId,warehouseId,weightKg,pricePerKg,principal.getName());return "redirect:/dashboard?sold";}catch(IllegalArgumentException ex){model.addAttribute("error",ex.getMessage());selections(model);return "sale-form";}}@GetMapping("/admin")String admin(Model model){model.addAttribute("users",users.findAll());model.addAttribute("materials",materials.findAll());model.addAttribute("remote",alerts.fetch());return "admin";}@PostMapping("/admin/users/{id}/role")String role(@PathVariable Long id,@RequestParam String role,Principal principal){if(!java.util.Set.of("ADMIN","MANAGER","STAFF").contains(role))throw new IllegalArgumentException("Invalid role");AppUser user=users.findById(id).orElseThrow();if(user.email.equalsIgnoreCase(principal.getName())&&!role.equals("ADMIN"))return "redirect:/admin?self";user.role=role;users.save(user);return "redirect:/admin";}@PostMapping("/admin/materials/{id}/delete")String delete(@PathVariable Long id,Model model){try{materials.deleteById(id);}catch(Exception ex){return "redirect:/admin?referenced";}return "redirect:/admin";}@PostMapping("/admin/alerts")String alert(@RequestParam String message,@RequestParam String severity){return "redirect:/admin?"+(alerts.create(message,severity)?"alertCreated":"alertOffline");}}